import{_ as s,C as i,o as n,c as t,E as r,a2 as l}from"./chunks/framework.Cm6XCzck.js";const u=JSON.parse('{"title":"别让 Agent 立刻写代码——也别盲信它的计划","description":"","frontmatter":{"title":"别让 Agent 立刻写代码——也别盲信它的计划","date":"2026-08-17","column":"open-source-engineering","category":"daily","article_type":"technical-analysis","edition":"research-center","research_question":"How can a reviewable planning artifact reduce requirement omissions in complex coding-agent tasks without turning a flawed plan into a new source of authority?","summary":"复杂任务需要执行前计划，但计划不是新的权威规格。它必须逐条映射原始需求、真实代码位置和验证方法，并在执行中记录偏差；否则一份流畅但错误的计划会比没有计划更危险。","sources":["research/manual-runs/2026-08-17-high-quality-article-pipeline/10-forum-demand-discovery-2026-08-18.md","research/manual-runs/2026-08-17-high-quality-article-pipeline/11-two-topic-deep-reading-and-fact-matrix.md","research/manual-runs/2026-08-17-high-quality-article-pipeline/12-two-topic-article-briefs.md"],"item_id":"MANUAL-20260817-PLAN","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-17-reviewable-agent-plan-cover.webp","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/engineering/2026-08-17-reviewable-agent-plan.md","filePath":"zh/engineering/2026-08-17-reviewable-agent-plan.md","lastUpdated":1787026891000}'),p={name:"zh/engineering/2026-08-17-reviewable-agent-plan.md"};function h(o,a,k,g,d,c){const e=i("ArticleCover");return n(),t("div",null,[r(e,{image:"/assets/covers/daily-2026-08-17-reviewable-agent-plan-cover.webp",kicker:"开源工程 · 研究文章",title:"别让 Agent 立刻写代码——也别盲信它的计划",summary:"复杂任务需要执行前计划，但计划不是新的权威规格。它必须逐条映射原始需求、真实代码位置和验证方法，并在执行中记录偏差；否则一份流畅但错误的计划会比没有计划更危险。",version:"MANUAL-20260817-PLAN",status:"Independent Editorial PASS · 2026-08-18",languageHref:"/en/engineering/2026-08-17-reviewable-agent-plan",languageLabel:"English"}),a[0]||(a[0]=l(`<h1 id="别让-agent-立刻写代码——也别盲信它的计划" tabindex="-1">别让 Agent 立刻写代码——也别盲信它的计划 <a class="header-anchor" href="#别让-agent-立刻写代码——也别盲信它的计划" aria-label="Permalink to &quot;别让 Agent 立刻写代码——也别盲信它的计划&quot;">​</a></h1><p>大仓库里的 coding agent 常见两种失败。</p><p>第一种，它收到“重构认证流程”后马上开始改文件。两小时后测试通过了一部分，但审计日志、迁移兼容和一个边缘分支完全没做。</p><p>第二种看起来更成熟：Agent 先写了一份结构漂亮的计划，人类点了批准。问题是计划在第一步就误解了权限边界。后续 Agent 严格照做，于是错误不再是一个局部补丁，而是被系统化地传播到多个模块和测试。</p><p>因此，“先计划还是先编码”不是这篇文章真正的问题。更重要的问题是：<strong>计划在系统里拥有什么权威？</strong></p><h2 id="计划确实必要-但证据没有说-有计划就更好" tabindex="-1">计划确实必要，但证据没有说“有计划就更好” <a class="header-anchor" href="#计划确实必要-但证据没有说-有计划就更好" aria-label="Permalink to &quot;计划确实必要，但证据没有说“有计划就更好”&quot;">​</a></h2><p>Cursor 的官方 Agent 实践把 Plan Mode 描述为四个步骤：先研究代码库，提出澄清问题，生成带文件路径和代码引用的实施计划，然后等待用户批准。文档也明确提醒，小改动或高度熟悉的任务不一定需要详细计划。<a href="https://cursor.com/blog/agent-best-practices" target="_blank" rel="noreferrer">[1]</a></p><p>这种做法直觉上合理。论坛里的大项目指南也反复建议短会话、Git 检查点、先总结目标、先列计划、再用测试保持成功条件可见。<a href="https://forum.cursor.com/t/an-idiots-guide-to-bigger-projects/23646" target="_blank" rel="noreferrer">[2]</a> 但经验帖只能证明这种工作法有人需要，不能证明每一条都提高成功率。</p><p>更有价值的证据来自 2025 年的 <a href="https://arxiv.org/abs/2511.04064" target="_blank" rel="noreferrer">E2EDevBench 研究</a>。研究从 PyPI 筛选 50 个 Python 项目，覆盖 2024-Q1 到 2025-Q1，平均每个项目 19.2 个文件、2011.5 行代码和 119.7 个测试。研究者在统一的 SWE-Agent 工具链上比较三种顺序工作流，并分别使用 Gemini-2.5-Pro 与 Flash。<a href="https://arxiv.org/abs/2511.04064" target="_blank" rel="noreferrer">[3]</a></p><p>最佳单一组合 Developer-Tester + Pro 的需求实现率是 53.50%。在三种工作流的均值中，Developer-Tester 是 49.48%，Single 是 45.72%，加入独立 Designer 的 Designer-Developer-Tester 却只有 27.71%。<a href="https://arxiv.org/abs/2511.04064" target="_blank" rel="noreferrer">[3]</a></p><p>这组结果直接否定了一个过度简单的结论：多一个规划角色、多一份设计文档，并不天然更可靠。</p><h2 id="最危险的计划会取代原始需求" tabindex="-1">最危险的计划会取代原始需求 <a class="header-anchor" href="#最危险的计划会取代原始需求" aria-label="Permalink to &quot;最危险的计划会取代原始需求&quot;">​</a></h2><p>为什么带 Designer 的工作流最差？论文作者检查轨迹后提出一个解释：Developer 收到看似权威的设计计划后，会优先服从计划，而不再直接核对同时存在的原始需求。如果设计计划有误，错误就被忠实地向下游实现和测试传播。<a href="https://arxiv.org/abs/2511.04064" target="_blank" rel="noreferrer">[3]</a></p><p>这是作者的机制归因，不是单独随机化“计划质量”后的因果结论。额外 handoff、上下文压缩或特定 prompt 也可能解释部分差异。但它暴露了一个真实的工程风险：<strong>派生文档发生权威倒置。</strong></p><p>原始需求本应是 canonical input，计划只是对它的解释和执行提案。系统却把流畅、结构化的计划当成更高权威，导致后续 Agent 即使忠实执行，也只是更有效率地偏离用户意图。</p><p>这和人类团队里的设计文档没有本质区别。文档越正式，读者越容易假设它已经完成核对。Agent 又特别擅长把一个明确计划执行得连贯，因此上游的一处遗漏会获得比临时编码更大的传播半径。</p><h2 id="失败更多来自遗漏和误解-而不只是代码不会写" tabindex="-1">失败更多来自遗漏和误解，而不只是代码不会写 <a class="header-anchor" href="#失败更多来自遗漏和误解-而不只是代码不会写" aria-label="Permalink to &quot;失败更多来自遗漏和误解，而不只是代码不会写&quot;">​</a></h2><p>E2EDevBench 对 1000 条未实现需求进行了失败分析。样本来自 50 个项目、Pro 模型和三类工作流，先由 LLM 预标注，再由人类修订。在这组特定样本中，Task Planning 根因占 55.8%：需求遗漏 27.9%，需求误解 22.2%，架构设计错误 5.6%。Task Execution 占 38.6%，Task Verification 占 5.7%。<a href="https://arxiv.org/abs/2511.04064" target="_blank" rel="noreferrer">[3]</a></p><p>这些数字不能被写成“所有 Agent 失败中 55.8% 来自规划”。研究只有两个 Gemini 模型，任务是从需求文档重建中等规模 PyPI 项目，不等同于真实企业大仓库的迁移和重构；评估还依赖 Test Migration Agent 与 LLM judge。</p><p>但更窄的判断成立：只在代码生成能力上继续加码，可能修不到最常见的上游缺口。Agent 可以写出语法正确、局部测试通过的代码，同时完全漏掉一个没有进入计划的需求。</p><p>另一项 79 页的观察研究 <a href="https://suproteem.is/assets/files/agents.pdf" target="_blank" rel="noreferrer">AI Agents and Higher-Order Work</a>提供了不同方向的信号。作者分析 1000 家企业、119,960 名匹配到职业特征的 Cursor 用户；消息意图子样本覆盖 399 家企业。在第一条消息中，Plan 的基准率约为 4.21%。工作经验增加一个标准差（约七年）与 Plan rate 增加 0.45 个百分点相关，相对基准约高 11%。<a href="https://ssrn.com/abstract=5713646" target="_blank" rel="noreferrer">[4]</a></p><p>这仍然不是因果证明。论文的意图分类器没有报告独立人工准确率，回归 R² 很低，计划率、经验和 Agent 输出接受率也可能共同受任务类型影响。它最多支持一个谨慎结论：更有经验的用户更常在执行前寻求对齐，而不是“计划一定让 Agent 更好”。</p><h2 id="一个计划应该是六段可审查合同" tabindex="-1">一个计划应该是六段可审查合同 <a class="header-anchor" href="#一个计划应该是六段可审查合同" aria-label="Permalink to &quot;一个计划应该是六段可审查合同&quot;">​</a></h2><p>复杂任务需要的不是一篇文笔流畅的“实施设想”，而是一份可以逐项查错的派生工件。最小 Plan Contract 可以分成六段：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">requirements_map</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">requirement_id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">R1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    source</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">issue/spec 原文位置</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    interpretation</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Agent 对该要求的可核对解释</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    planned_steps</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">S1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">S3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">code_map</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">step_id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">S1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    files_or_symbols</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">真实路径或符号</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    evidence</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">搜索结果、调用关系或现有测试</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">dependencies_and_risks</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">前置迁移、外部接口、权限、并发或回滚风险</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">verification</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">每条 requirement 对应的测试、静态检查或人工验收</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">non_goals</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">本次明确不改什么，以及原因</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">execution_delta</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">执行中偏离了哪一步、发现了什么、是否需要重新批准</span></span></code></pre></div><p>这份合同有三个关键性质。</p><p>第一，需求到步骤必须可追踪。计划不能只按模块写“更新服务层、补测试”，而要让审阅者看见每条需求落在哪个步骤、如何验证。没有映射的需求，就是执行前已经可见的遗漏。</p><p>第二，代码位置必须有证据。文件名、符号和依赖关系应来自实际仓库探索，而不是从任务标题猜测。Cursor 官方 Plan Mode 要求文件路径和代码引用，价值就在这里。<a href="https://cursor.com/blog/agent-best-practices" target="_blank" rel="noreferrer">[1]</a></p><p>第三，计划永远不能覆盖原始需求。Developer、Tester 和 reviewer 都应同时看到 canonical requirements。计划发生冲突时，系统应回到原始需求并重新规划，而不是默认“既然已批准就继续执行”。</p><h2 id="人类批准-不是一个充分门禁" tabindex="-1">“人类批准”不是一个充分门禁 <a class="header-anchor" href="#人类批准-不是一个充分门禁" aria-label="Permalink to &quot;“人类批准”不是一个充分门禁&quot;">​</a></h2><p>一段结构漂亮、术语正确的文字很容易被快速批准。真正的计划评审不应问“读起来合理吗”，而应问：</p><ul><li>每条原始需求是否有落点？</li><li>每个高风险步骤是否有证据和验证？</li><li>是否存在计划新增、但原始需求没有授权的范围？</li><li>Tester 是否仍从原始需求生成验收，而不是只从计划生成测试？</li><li>执行中发现新事实后，偏差是否可见并触发重新评审？</li></ul><p>这也是为什么计划应保存为仓库工件，而不是只留在一段会被压缩的聊天历史里。它需要被 diff、评论、版本化，并与执行基线绑定。</p><h2 id="不是每个任务都值得走重型计划门" tabindex="-1">不是每个任务都值得走重型计划门 <a class="header-anchor" href="#不是每个任务都值得走重型计划门" aria-label="Permalink to &quot;不是每个任务都值得走重型计划门&quot;">​</a></h2><p>计划有成本。已知文件与位置、影响范围很小、验证明确的单行修复，可以走轻量通道：一句目标、一个目标位置、一条验证即可。强制所有任务填写六段合同，会把工程控制变成表格劳动。</p><p>真正适合强制 Plan Review 的，是跨模块改动、数据迁移、权限变化、公开 API 变更、难以回滚的操作，以及任何一个遗漏都可能让“测试通过”仍然无法代表完成的任务。</p><h2 id="尚未被证明的部分" tabindex="-1">尚未被证明的部分 <a class="header-anchor" href="#尚未被证明的部分" aria-label="Permalink to &quot;尚未被证明的部分&quot;">​</a></h2><p>本文的六段 Plan Contract 是基于产品机制、受控实验和观察研究提出的工程综合，尚没有独立实验直接证明它在真实大仓库中降低多少遗漏。下一步应在真实任务上比较：无计划、自由文本计划和可追踪计划三种条件下的需求完成率、返工次数、审阅时间与成本。</p><p>但现有证据已经足以排除两个危险的极端：让 Agent 收到复杂任务后立刻写代码，和让 Agent 收到一份未经核对的计划后无条件服从。</p><p>计划最有价值的时刻，不是它让 Agent 显得更有条理，而是它让错误在写代码之前就有机会被看见。</p><h2 id="来源" tabindex="-1">来源 <a class="header-anchor" href="#来源" aria-label="Permalink to &quot;来源&quot;">​</a></h2><ol><li><a href="https://cursor.com/blog/agent-best-practices" target="_blank" rel="noreferrer">Cursor：Best practices for coding with agents</a></li><li><a href="https://forum.cursor.com/t/an-idiots-guide-to-bigger-projects/23646" target="_blank" rel="noreferrer">Cursor Forum：An Idiot&#39;s Guide To Bigger Projects</a></li><li><a href="https://arxiv.org/abs/2511.04064" target="_blank" rel="noreferrer">Benchmarking and Studying the LLM-based Agent System in End-to-End Software Development</a></li><li><a href="https://suproteem.is/assets/files/agents.pdf" target="_blank" rel="noreferrer">AI Agents and Higher-Order Work：作者公开 PDF</a>；<a href="https://ssrn.com/abstract=5713646" target="_blank" rel="noreferrer">SSRN 记录</a></li></ol>`,42))])}const m=s(p,[["render",h]]);export{u as __pageData,m as default};
